/**  The file exists but points somewhere else, usually an old port. */
"stale" | "missing";

/**  Objects whose YAML the UI can show. */
export type ResourceKind = "pod" | "deployment" | "service";

export type Restart = "no" | "onFailure" | "unlessStopped" | "always";

/**  A column of a query result, which may not belong to any one table. */
export type ResultColumn = {
	name: string,
	typeName: string,
	kind: ValueKind,
};

/**  Why a route can't be reached right now. */
export type RouteDown = 
/**  The container is stopped or gone. */
"stopped" | 
/**  The container runs but doesn't publish the port to the Mac. */
"notPublished";

export type RouteKind = "container" | "custom";

/**  One page of a table. */
export type RowPage = {
	columns: Column[],
	rows: Value[][],
	/**  Rows matching the filters, counted up to a cap; or the table's estimate when unfiltered. */
	total: number | null,
	/**  The count stopped at the cap: there are at least this many. */
	totalCapped: boolean,
	/**  Milliseconds; always a finite number. */
	elapsedMs: number,
	/**  Why the grid can't edit these rows, when it can't. */
	readOnlyReason: string | null,
};

export type RowUpdate = {
	/**  The primary key of the row as it was read. */
	key: Cell[],
	set: Cell[],
};

/**  One page of a table, filtered and sorted in the database. */
export type RowsRequest = {
	table: TableRef,
	filters: Filter[],
	sort: Sort | null,
	limit: number,
	offset: number,
};

/**  What the Run container sheet asks for. */
export type RunSpec = {
	image: string,
	name: string | null,
	ports: PortMapping[],
	env: EnvVar[],
	storage: StorageMapping[],
	restart: Restart,
	/**  Replaces the image's default command when set, already split into arguments. */
	command: string[] | null,
	/**  `linux/amd64` to run an Intel image under Rosetta or QEMU. */
	platform: string | null,
};

export type SavedQuery = {
	id: string,
	name: string,
	connectionId: string | null,
	sql: string,
};

export type ScanReport = {
	reference: string,
	/**  Worst first. */
	vulnerabilities: Vulnerability[],
};

export type SegmentKind = "project" | "standalone" | "kubernetes";

/**  An open connection, as the workspace header and the safe-mode banner show it. */
export type ServerInfo = {
	id: string,
	name: string,
	engine: Engine,
	provider: Provider | null,
	version: string,
	capabilities: Capabilities,
	environment: Environment,
	/**  Writes are blocked: a production connection in safe mode. */
	readOnly: boolean,
	/**  When writes were allowed for a while, when that ends. */
	writableUntilMs: number | null,
};

export type ServicePort = {
	port: number,
	target: string,
	protocol: string,
	nodePort: number | null,
};

export type ServiceSummary = {
	namespace: string,
	name: string,
	kind: string,
	clusterIp: string | null,
	ports: ServicePort[],
	/**  `localhost:port` for a `LoadBalancer` service: k3s binds it in the VM and Lima forwards it. */
	fromMac: string | null,
};

/**  A tab in the Settings window's toolbar. */
export type SettingsPane = "general" | "engine" | "storage" | "kubernetes" | "docker" | "about";

/**  Switches the open Settings window to a pane. */
export type SettingsPaneShown = SettingsPane;

export type Severity = "critical" | "high" | "medium" | "low" | "unknown";

/**  What a terminal receives: text to draw, then one `closed` when the shell exits. */
export type ShellEvent = { kind: "output"; text: string } | { kind: "closed" };

export type Sort = {
	column: string,
	descending: boolean,
};

/**  One stats reading, already turned into the numbers the UI draws. */
export type StatsSample = {
	cpuPercent: number | null,
	memoryBytes: number,
	memoryLimitBytes: number,
	networkRxBytes: number,
	networkTxBytes: number,
	diskReadBytes: number,
	diskWriteBytes: number,
};

/**  A volume by name, or a folder on the Mac by absolute path. */
export type StorageMapping = {
	source: string,
	target: string,
	readOnly: boolean,
};

export type Table = {
	schema: string | null,
	name: string,
	kind: TableKind,
	/**  The database's own estimate, cheap to read; not an exact count. */
	rowEstimate: number | null,
	sizeBytes: number | null,
	columns: Column[],
	indexes: Index[],
};

export type TableKind = "table" | "view" | "collection";

/**  Points at one table from the UI. */
export type TableRef = {
	schema: string | null,
	name: string,
};

/**  One kind of thing taking space in the engine. */
export type UsageGroup = {
	count: number,
	/**  How many are used by a container, or for the build cache, in use by a build. */
	active: number,
	sizeBytes: number,
	/**  What a clean-up would free. */
	reclaimableBytes: number,
};

/**
 *  One cell as the grid shows it. Integers beyond 2^53 and exact decimals stay text so nothing is
 *  rounded on the way to JavaScript.
 */
export type Value = null | boolean | number | null | string | 
/**  A JSON object or array: `jsonb`, MySQL `JSON`, a nested MongoDB document. */
JsonDocument;

/**  How the grid aligns, edits and filters a column. */
export type ValueKind = "number" | "text" | "bool" | "json" | "time" | "binary" | "other";

/**
 *  Apple Virtualization keeps Rosetta; krunkit gives freed memory back to macOS. The choice is
 *  fixed when the engine is created.
 */
export type VmType = "vz" | "krunkit";

/**  One entry of a folder inside a volume. */
export type VolumeFile = {
	name: string,
	kind: VolumeFileKind,
	sizeBytes: number,
	modifiedAt: number,
};

export type VolumeFileKind = "file" | "directory" | "link" | "other";

export type VolumeSummary = {
	name: string,
	driver: string,
	createdAt: string | null,
	/**  `None` while Docker hasn't measured it. */
	sizeBytes: number | null,
	project: string | null,
	/**  Created for a container without a name; a 64-character hash. */
	anonymous: boolean,
	usedBy: VolumeUser[],
};

/**  A container using a volume, and where it sees it. */
export type VolumeUser = {
	containerId: string,
	container: string,
	mountedAt: string,
	running: boolean,
};

export type Vulnerability = {
	id: string,
	package: string,
	installed: string,
	/**  The version that fixes it, when one exists. */
	fixed: string | null,
	severity: Severity,
	title: string | null,
	url: string | null,
	/**  The layer or file it was found in, such as `debian 13.1` or `app/package-lock.json`. */
	target: string,
};

/* Tauri Specta runtime */
type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

